  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Validates whether a booking can be made for the given trip by checking all eligibility rules.
   * Algorithm:
   *   if customer == null OR trip == null OR bookingDate == null then return false
   *   if trip.getBookedSeats() + numberOfSeats > trip.numberOfSeats then return false
   *   if not (bookingDate is more than 2 hours before trip.departureTime) then return false
   *   for each existing booking in customer.bookings:
   *     if booking.overlapsWith(trip) AND booking.bookingDate == trip.departureDate then return false
   *   return true
   * Related Features: customer.bookings, trip.numberOfSeats, trip.departureTime, trip.departureDate, trip.getBookedSeats()
   * Related Classes: Customer, Trip, Booking
   * Input: none (operates on instance fields: customer, trip, numberOfSeats, bookingDate)
   * Output: boolean - true if eligible, false otherwise
   * Pre-condition: none
   * Post-condition: none (validation only)
   * <!-- end-model-doc -->
   * @model kind="operation"
   *        annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean isBookingEligible()
  {
    if (customer == null || trip == null || bookingDate == null) return false;
    
    if (trip.getBookedSeats() + numberOfSeats > trip.getNumberOfSeats()) return false;
    
    String departureTime = trip.getDepartureTime();
    if (departureTime == null) return false;
    String[] timeParts = departureTime.split(":");
    int depHour = Integer.parseInt(timeParts[0]);
    int depMin = Integer.parseInt(timeParts[1]);
    int depTotalMin = depHour * 60 + depMin;
    
    Calendar cal = Calendar.getInstance();
    cal.setTime(bookingDate);
    int bookHour = cal.get(Calendar.HOUR_OF_DAY);
    int bookMin = cal.get(Calendar.MINUTE);
    int bookTotalMin = bookHour * 60 + bookMin;
    
    if (depTotalMin - bookTotalMin <= 120) return false;
    
    if (customer.getBookings() != null) {
      for (Booking existingBooking : customer.getBookings()) {
        if (existingBooking != this && existingBooking.overlapsWith(trip)) {
          if (existingBooking.getBookingDate() != null) {
            Calendar existingCal = Calendar.getInstance();
            existingCal.setTime(existingBooking.getBookingDate());
            Calendar thisCal = Calendar.getInstance();
            thisCal.setTime(bookingDate);
            if (existingCal.get(Calendar.YEAR) == thisCal.get(Calendar.YEAR) &&
                existingCal.get(Calendar.DAY_OF_YEAR) == thisCal.get(Calendar.DAY_OF_YEAR)) {
              return false;
            }
          }
        }
      }
    }
    
    return true;
  }

